func test_databricks_TestDatabricks_test_to_char_is_numeric_transpile_to_cast(self *Case, a Args) Value {
	var sql, expression, to_char_exp, result Value
	_ = []Value{sql, expression, to_char_exp, result}
	self.Do(557, func() { sql = "SELECT TO_CHAR(12345, '#')" })
	self.Do(558, func() { expression = Call(G("sqlglot.parse_one"), sql, Kw("read", "dremio")) })
	self.Do(560, func() { to_char_exp = M(expression, "find", A(G("sqlglot.exp"), "ToChar")) })
	self.Do(561, func() { Assert(IsNot(to_char_exp, nil)) })
	self.Do(562, func() { Assert(Is(M(A(to_char_exp, "args"), "get", "is_numeric"), true)) })
	self.Do(564, func() {
		result = Item(Call(G("sqlglot.transpile"), sql, Kw("read", "dremio"), Kw("write", "databricks")), 0)
	})
	self.Do(565, func() { Assert(In("CAST(12345 AS STRING)", result)) })
	return nil
}

